(* [comment removed for export] *)
Definition ugw_words_exit (ra sp gp tp t0 t1 t2 s0 a1 a2 a3 a4 a5 a6 a7 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D n : Z) : machine_state -> Prop :=
  fun ms' => exists (s2' s3' s4' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (D + 4 * n)) (Z_to_bv 64 (D + 4 * n)) a1 a2 a3 a4 a5 a6 a7 s2' s3' s4' s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x12f734) fc None m' (seg_rom asegs)
    /\ munch [(D, D + 4 * n)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma ugw_words_loop : forall (k : nat) (j : Z)
    (ra sp gp tp t0 t2 a1 a2 a3 a4 a5 a6 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 : word) F fc (m : mem) (DA n : Z),
  Z.of_nat k = n - j -> 0 <= j -> (1 <= k)%nat -> n < 2^26 ->
  0 < DA -> DA mod 4 = 0 -> DA + 4 * n <= 2^47 ->
  (DA + 4 * n <= 0x7fff7000 \/ 0x10007fff8000 <= DA) ->
  wr_at asegs m DA (4 * n) -> acc asegs m DA (4 * n) -> mem_inv asegs m ->
  evt asegs (ugw_words_exit ra sp gp tp t0 (Z_to_bv 64 2147450880) t2 (Z_to_bv 64 1) a1 a2 a3 a4 a5 a6 (Z_to_bv 64 DA) s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 (Z_to_bv 64 1) F fc m DA n)
    (MS (mkR ra sp gp tp t0 (Z_to_bv 64 2147450880) t2 (Z_to_bv 64 1) (Z_to_bv 64 (DA + 4 * j)) (Z_to_bv 64 (DA + 4 * j)) a1 a2 a3 a4 a5 a6 (Z_to_bv 64 DA)
             (Z_to_bv 64 (n - j)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 (Z_to_bv 64 1))
        F (Z_to_bv 64 0x12f6e8) fc None m (seg_rom asegs)).
Proof.
